import React, { useEffect, useState } from "react";
import axios from "axios";
import { Html5QrcodeScanner } from "html5-qrcode";
import { useNavigate } from "react-router-dom";

function QRScanner() {
  const [user, setUser] = useState(null);
  const [message, setMessage] = useState("");

  const navigate = useNavigate();

  /* =============================
   ADMIN LOGIN CHECK
============================= */

  useEffect(() => {
    const admin = localStorage.getItem("admin");

    if (!admin) {
      alert("Please login as Admin");
      navigate("/admin-login");
    }
  }, [navigate]);

  /* =============================
   START QR SCANNER
============================= */

  useEffect(() => {
    let scanner;

    const startScanner = () => {
      scanner = new Html5QrcodeScanner(
        "reader",
        { fps: 10, qrbox: 250 },
        false,
      );

      scanner.render(
        (result) => {
          scanner.clear();

          verifyUser(result);
        },
        (error) => {
          console.log(error);
        },
      );
    };

    startScanner();

    return () => {
      if (scanner) {
        scanner.clear().catch((err) => console.log(err));
      }
    };
  }, []);

  /* =============================
   VERIFY USER
============================= */

  const verifyUser = async (id) => {
    try {
      const res = await axios.get(`http://localhost:5000/verify-user/${id}`);

      if (res.data.success) {
        setUser(res.data.user);
        setMessage("User Verified");

        await axios.put(`http://localhost:5000/mark-attendance/${id}`);
      } else {
        setMessage("User NOT Registered");
      }
    } catch (error) {
      console.log(error);
      setMessage("Server Error");
    }
  };

  /* =============================
   UI
============================= */

  return (
    <div style={{ padding: "20px" }}>
      <h2>Admin QR Scanner</h2>

      <div id="reader" style={{ width: "300px" }}></div>

      <h3>{message}</h3>

      {user && (
        <div>
          <p>Name : {user.name}</p>
          <p>College : {user.college_name}</p>
          <p>Phone : {user.phone}</p>
          <p>Event ID : {user.event_id}</p>

          <p style={{ color: "green" }}>Attendance Marked</p>
        </div>
      )}
    </div>
  );
}

export default QRScanner;
